const RETRYABLE_STATUSES = new Set([408, 429, 500, 502, 503, 504]);
const RETRYABLE_METHODS = new Set(["GET", "HEAD", "OPTIONS", "PUT", "DELETE"]);

function hasIdempotencyKey(headers) {
  if (headers == null) {
    return false;
  }

  if (typeof headers.has === "function") {
    return headers.has("Idempotency-Key");
  }

  return Object.keys(headers).some(
    (name) => name.toLowerCase() === "idempotency-key"
  );
}

function isRetryableRequest(options) {
  const methodValue = options.method === undefined ? "GET" : options.method;
  const method = String(methodValue).toUpperCase();

  if (RETRYABLE_METHODS.has(method)) {
    return true;
  }

  return (
    (method === "POST" || method === "PATCH") &&
    hasIdempotencyKey(options.headers)
  );
}

function containsOnlyDigits(value) {
  if (typeof value !== "string" || value.length === 0) {
    return false;
  }

  for (let index = 0; index < value.length; index += 1) {
    const code = value.charCodeAt(index);
    if (code < 48 || code > 57) {
      return false;
    }
  }

  return true;
}

function createAbortError() {
  const error = new Error("The operation was aborted");
  error.name = "AbortError";
  return error;
}

export function createResilientFetch({
  fetch,
  sleep,
  random = Math.random,
  maxAttempts = 4,
  baseDelayMs = 200,
  maxDelayMs = 5000,
}) {
  function getBackoffDelay(retryNumber) {
    const limit = Math.min(
      maxDelayMs,
      baseDelayMs * 2 ** (retryNumber - 1)
    );
    return Math.floor(random() * limit);
  }

  return async function rfetch(url, options = {}) {
    const requestIsRetryable = isRetryableRequest(options);
    let attempt = 1;

    while (true) {
      const signal = options.signal;
      if (signal && signal.aborted) {
        throw createAbortError();
      }

      let response;

      try {
        response = await fetch(url, options);
      } catch (error) {
        if (error && error.name === "AbortError") {
          throw error;
        }

        if (!requestIsRetryable || attempt >= maxAttempts) {
          throw error;
        }

        await sleep(getBackoffDelay(attempt), options.signal);
        attempt += 1;
        continue;
      }

      if (response.ok === true) {
        return response;
      }

      if (!RETRYABLE_STATUSES.has(response.status)) {
        return response;
      }

      if (!requestIsRetryable || attempt >= maxAttempts) {
        return response;
      }

      const retryAfter = response.headers.get("Retry-After");
      let delayMs;

      if (containsOnlyDigits(retryAfter)) {
        delayMs = Number(retryAfter) * 1000;

        if (delayMs > maxDelayMs) {
          return response;
        }
      } else {
        delayMs = getBackoffDelay(attempt);
      }

      await sleep(delayMs, options.signal);
      attempt += 1;
    }
  };
}
